mapper.select:
SELECT DISTINCT student_record.id FROM student student_record LEFT JOIN batch_student_eligibility eligibility ON eligibility.student_id = student_record.id LEFT JOIN room_assignment residency ON residency.student_id = student_record.id AND residency.assignment_status = 'ACTIVE' LEFT JOIN room room_record ON room_record.id = residency.room_id LEFT JOIN dormitory_floor floor_record ON floor_record.id = room_record.floor_id LEFT JOIN dormitory_building building_record ON building_record.id = floor_record.building_id WHERE student_record.housing_eligibility = 'ELIGIBLE'
AND eligibility.batch_id IN #{id}
AND student_record.major_id IN #{id}
AND student_record.grade_year IN #{value}
AND student_record.degree_level IN #{value}
AND student_record.student_category IN #{value}
AND building_record.id IN #{id}
AND NOT EXISTS ( SELECT 1 FROM bed_assignment assignment_record WHERE assignment_record.student_id = student_record.id AND assignment_record.assignment_status = 'ACTIVE'
AND assignment_record.batch_id IN #{id}
)
AND EXISTS ( SELECT 1 FROM bed_confirmation_request confirmation_record WHERE confirmation_record.student_id = student_record.id AND confirmation_record.request_status = 'PENDING' )
ORDER BY student_record.id
